  return (
    <div className="app">
      <Header />
      <Home />
      <Footer />

      <Routes>
        <Route path="/" element={<Project/>} />
        <Route path="/city" element={<Projects/>} />
        <Route path="/cars" element={<Cars />} />
      </Routes>
    </div>
  );
}

export default App;
